#!/bin/bash
# shellcheck disable=all
set -euo pipefail
cargo install --path crates/slop-jeb-bin
body="$(jeb encode-jeb85 split-80 join-lines < "$(which jeb)")"
header="$(head -n 8 < "$0")"
echo -n "${header}"$'\n'"${body}"$'\n' > "$0"
exit
